public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    int n = nums.length;
    if (n == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Clean up null strings
    List<String> cleaned = new ArrayList<>();
    for (String s : strings) {
        cleaned.add(s == null ? "" : s);
    }
    // Find the maximum possible length (length of the shortest string)
    int maxLen = Integer.MAX_VALUE;
    for (String s : cleaned) {
        maxLen = Math.min(maxLen, s.length());
    }
    if (maxLen == 0) {
        return 0;
    }
    // Iterate from longest possible length down to 1
    for (int len = maxLen; len >= 1; len--) {
        String first = cleaned.get(0);
        // Generate all substrings of length len from the first string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            candidates.add(first.substring(i, i + len));
        }
        // For each candidate, check all other strings
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (int idx = 1; idx < cleaned.size(); idx++) {
                String s = cleaned.get(idx);
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        if (grid[i] == null) {
            visited[i] = new boolean[0];
            continue;
        }
        visited[i] = new boolean[grid[i].length];
    }

    int deposits = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) continue;
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // BFS/DFS to mark all connected '@'
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && grid[nr] != null && nc >= 0 && nc < grid[nr].length) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

