public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            // If the string contains characters outside 'a'-'z', treat them as is
            // by expanding the frequency array dynamically (not required for the problem constraints)
            // For simplicity, we ignore such characters.
            continue;
        }
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Ascending pass: pick smallest available character
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
                break;
            }
        }
        // Descending pass: pick largest available character
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
                break;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int num : nums) totalSum += num;
    int n1 = n / 2;
    int n2 = n - n1;
    @SuppressWarnings("unchecked")
    List<Long>[] sums1 = new ArrayList[n1 + 1];
    @SuppressWarnings("unchecked")
    List<Long>[] sums2 = new ArrayList[n2 + 1];
    for (int i = 0; i <= n1; i++) sums1[i] = new ArrayList<>();
    for (int i = 0; i <= n2; i++) sums2[i] = new ArrayList<>();
    for (int mask = 0; mask < (1 << n1); mask++) {
        int size = Integer.bitCount(mask);
        long sum = 0;
        for (int i = 0; i < n1; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[i];
        }
        sums1[size].add(sum);
    }
    for (int mask = 0; mask < (1 << n2); mask++) {
        int size = Integer.bitCount(mask);
        long sum = 0;
        for (int i = 0; i < n2; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[n1 + i];
        }
        sums2[size].add(sum);
    }
    @SuppressWarnings("unchecked")
    Set<Long>[] set2 = new HashSet[n2 + 1];
    for (int i = 0; i <= n2; i++) {
        set2[i] = new HashSet<>(sums2[i]);
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        long target = (totalSum * k) / n;
        for (int k1 = 0; k1 <= k; k1++) {
            int k2 = k - k1;
            if (k1 > n1 || k2 > n2) continue;
            for (long sum1 : sums1[k1]) {
                long need = target - sum1;
                if (set2[k2].contains(need)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) without paying any cost
        return 0;
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue; // skip null words
        }
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } else {
                // ignore non-alphabetic characters
            }
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    if (total > n) {
        // If there are more possible codes than substrings, it's impossible
        // but we still need to check all substrings
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;
    // Slide over the rest of the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) {
                return true; // all codes found early
            }
        }
    }
    return count == total;
}

