public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }
    try {
        ArrayList<Integer> small = new ArrayList<>();
        ArrayList<Integer> large = new ArrayList<>();
        int limit = (int) Math.sqrt(n);
        for (int i = 1; i <= limit; i++) {
            if (n % i == 0) {
                small.add(i);
                int counterpart = n / i;
                if (counterpart != i) {
                    large.add(counterpart);
                }
            }
        }
        // Combine small and reversed large to get ascending order
        int totalFactors = small.size() + large.size();
        if (k > totalFactors) {
            return -1;
        }
        if (k <= small.size()) {
            return small.get(k - 1);
        } else {
            // k is in the large part
            int indexInLarge = k - small.size() - 1; // 0-based
            // large is in descending order, so reverse index
            return large.get(large.size() - 1 - indexInLarge);
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return -1
        return -1;
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(c - top) == 32) { // 'a' - 'A' == 32
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = new int[1];
    Set<String> seen = new HashSet<>();
    dfs(s, 0, seen, max);
    return max[0];
}

private void dfs(String s, int index, Set<String> seen, int[] max) {
    if (index == s.length()) {
        max[0] = Math.max(max[0], seen.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            dfs(s, end, seen, max);
            seen.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in the current folder, no change
                break;
